// DenaivamPhalanx — built on DenaivamDecoy / DenaivamApex (no imports). Upload the built
// DenaivamPhalanx.mjs (node tools/build-bot.mjs DenaivamPhalanx), not this .src file.
// Plan:
//  1. ECONOMY AT HOME: workers mine the energy next to our base and the crystal closest to it
//     (walking distance); guard scouts stand over the energy nodes and the crystal and kill
//     enemy scouts and workers that come near. Mine as much as possible.
//  2. SOLDIERS: every crystal becomes soldiers (fighters). Free unit slots are kept for the
//     soldiers the remaining crystal can still pay for; only the rest become scouts.
//  3. PHALANX: the soldiers stay together in a tight block between our base and our crystal,
//     and fight together only against enemies that come into our area.
//  4. If the enemy has turrets near the center, the fighter upgrade (turrets ignore our
//     soldiers) is bought before any more soldiers.
//  5. Shortly before the zone starts to shrink (tick 400), everything marches on the center as
//     one group (the front waits for the slow ones). There the surround micro takes over:
//     focus fire to kill in one tick, encircle enemies from every side (fast scouts take the
//     far side so the target can't get away), first strike on enemies walking in, hurt soldiers
//     step back. Finally the army packs into the final circle (scouts inside, soldiers outside).

// =====================================================================
// BUILD ORDER — edit this.
// Items are bought top to bottom; `number` is how many of that item to buy.
// If an item only lacks energy, the bot saves up for it before buying anything later.
// If an item is impossible right now (not enough crystal, unit cap, too late...), it is
// skipped and stays owed; it is bought as soon as it becomes possible. Crystal items that
// can be paid go first. After the list (or while all of it is blocked) the bot decides by
// itself (FREE MODE): rebuild lost workers and guards, soldiers, then scouts in unit slots
// no soldier will need.
//
// Items:
//   "eWorker"           worker that gathers energy at home
//   "cWorker"           worker that gathers the crystal closest to our base
//   "GuardScout"        scout that guards our energy nodes and our crystal
//   "Soldier"           fighter (60 E + 15 C)
//   "Scout"             scout (guard job)
//   "CrystalRaiderScout" / "CrystalGuardScout" / "EnergyRaiderScout"  Apex scout jobs
//   "Tower"             turret near our base
//   "ScoutUpgrade"      15 C: all scouts speed 4 and 10 HP
//   "SoldierUpgrade"    20 C: turrets ignore all our soldiers (bought automatically when
//                       the enemy has turrets near the center, see PHALANX_UPGRADE_*)
//   "WallUpgrade"       50 E: walls 120 HP
// =====================================================================
const BUILD_ORDER = [
  { item: "eWorker", number: 3 },
  { item: "cWorker", number: 2 },
  { item: "GuardScout", number: 3 },
    { item: "cWorker", number: 4 },
  { item: "GuardScout", number: 2 },
  { item: "Soldier", number: 5 },
  {item: "SoldierUpgrade", number:1},
  { item: "Soldier", number: 40 },
    { item: "GuardScout", number: 40 },

];
// Build-order item name -> internal role used by the strategy code below.
const BUILD_ITEMS = {
  eworker: "eWorker", cworker: "cWorker",
  wallworker: "wallBuilderWorker", wallbuilderworker: "wallBuilderWorker",
  soldier: "Soldier", fighter: "Soldier",
  scout: "Scout", guardscout: "guardScout", homeguardscout: "guardScout",
  crystalraiderscout: "cRaiderScout", craiderscout: "cRaiderScout",
  crystalguardscout: "cRaiderScoutHome", craiderscouthome: "cRaiderScoutHome",
  energyraiderscout: "eRaiderScout", eraiderscout: "eRaiderScout",
  baseattackscout: "baseAttackerScout", baseattackerscout: "baseAttackerScout",
  tower: "defensiveTower", defensivetower: "defensiveTower",
  scoutupgrade: "ScoutUpgrade", scoutspeedupgrade: "ScoutUpgrade",
  soldierupgrade: "SoldierUpgrade", fighterupgrade: "SoldierUpgrade",
  wallupgrade: "WallUpgrade",
};
// Jobs handed to generic "Scout" purchases.
const SCOUT_JOBS = [["guardScout", 99]];

// AUTO UPGRADES (rules 3.1.0: each upgrade is bought once and covers every unit of its type):
// the scout upgrade (15 C: all scouts 10 HP, speed 4) once we have 3 scouts, and the fighter
// upgrade (20 C: turrets ignore all our soldiers) once enemy turrets show up while we have
// 2+ soldiers. Ahead of the build order. Set false to control them only from BUILD_ORDER.
const AUTO_UPGRADES = false;
// SOLDIER UPGRADE switch: false = never buy the fighter upgrade (20 C), neither from
// BUILD_ORDER nor automatically; the crystal goes to soldiers instead.
const SOLDIER_UPGRADE = true;

// TURRET AVOIDANCE: scouts never end a move inside a known enemy turret's range
// (Chebyshev 4 + SCOUT_TURRET_MARGIN), never attack from inside it, and a scout that finds
// itself inside one steps out first. Turrets do 4 damage a tick: a plain scout (5 HP) dies
// in 2 ticks, an upgraded one (10 HP) in 3. Off during the final zone retreat.
const SCOUT_AVOID_TURRETS = true;
const SCOUT_TURRET_MARGIN = 0;


// RUSH DEFENCE: an early enemy army at our base (scout rushes surround it, block deposits
// and kill it by tick ~80) gets a turret by the base first; the bot saves energy for it.
const RUSH_DEFENCE = true;
const RUSH_MIN_ENEMIES = 3;   // enemy scouts/soldiers near one of our bases
const RUSH_RADIUS = 14;       // "near" before RUSH_EARLY_TICK (a rush must be seen coming),
const RUSH_EARLY_TICK = 60;
const RUSH_BASE_RADIUS = 3;   // "near" after it (normal raids are not rushes)
const RUSH_ALERT_TICKS = 40;  // how long an alert (and saving for the turret) lasts
const RUSH_MAX_TURRETS = 2;   // one turret per 5 attackers, at most this many
const RUSH_UNTIL_TICK = 250;
// SIMPLIFIED: the look-ahead scout combat search (the main CPU cost) runs on a smaller budget.
const SCOUT_COMBAT_MICRO = true;

// ---- PHALANX (the army plan) ----
const GUARD_SCOUTS = 5;             // free mode keeps this many guard scouts alive...
const GUARD_SCOUTS_MAX = 16;        // ...and up to 2 more than the enemy scouts seen in our area
const GUARD_MEMORY = 40;            // (seen within the last this many ticks)
const GUARD_RADIUS = 7;             // guards attack enemy scouts/workers this close to their post
const GUARD_ENERGY_EVERY = 4;       // every 4th guard stands by the energy, the rest by the crystal
const GUARD_LOOKOUT = true;         // one guard watches the center (to spot enemy turrets there)
const GUARD_LOOKOUT_TICK = 150;     // ...from this tick, once there are 3+ guards
const PHALANX_CRYSTAL_MAX_WALK = 40; // the block stands by our crystal if it is this close
                                    // (walking distance), otherwise in front of our base
const PHALANX_FORWARD = 3;          // tiles from the crystal (or 5 from the base) toward the center
const PHALANX_DEFEND_RADIUS = 7;    // enemies this close to our base, nodes, crystal, workers
                                    // or the block are attacked
const PHALANX_LEASH = 10;           // soldiers never chase farther than this from the block
const PHALANX_FIGHT_RATIO = 1.0;  // fight enemy soldiers in our area only if their total HP is at
                                    // most this times ours (or they are at our base); else fall back
const PHALANX_RETREAT_HP = 6;       // hurt soldiers step out of an enemy soldier's reach
const UPGRADE_RESERVE_SOLDIERS = 3; // once we have this many soldiers, 20 crystal is kept for that
                                    // upgrade (enemy center turrets often appear late)
const PHALANX_UPGRADE_CENTER_RADIUS = 10; // enemy turrets this close to the center ->
                                    // buy the fighter upgrade before more soldiers
// ATTACK: the army leaves so that it reaches the center ATTACK_ARRIVE_BEFORE ticks before
// the zone starts shrinking (tick 400); it never leaves later than ATTACK_LATEST_TICK.
const ATTACK_ARRIVE_BEFORE = 12;
const ATTACK_LATEST_TICK = 380;
const ATTACK_GROUP_SPREAD = 2;      // the front waits until the group is this close behind
const ATTACK_ENGAGE_RADIUS = 9;     // enemies this close to the army are fought
const SCOUTS_JOIN_ATTACK = true;    // scouts march and fight with the soldiers
const BREACH_DAMAGE = 12;           // enemy walls in the way are broken at about this much damage per
                                    // tick (two soldiers); the attack leaves earlier to make up for it
